-- 28 September 2026 daily current-affairs desk.
-- Every brief was checked against the linked primary official source.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-28-eci-sir-access-and-ecinet-review$$, $$2026-09-28$$,
  $$Election Commission expands SIR access measures and orders an ECINet review$$,
  $$The Election Commission directed house visits for certain electors issued notices during Special Intensive Revision (SIR), asked districts to create help desks for vulnerable groups, and constituted a committee with an independent IIT or IIIT expert to review ECINet compliance. It also extended stated claims-and-objections timelines in Delhi and Maharashtra.$$,
  $$This is an election-administration brief. It tests the roles of BLOs, EROs and DEOs, and distinguishes continuous electoral-roll updating from the time-bound SIR process.$$,
  $$A Booth Level Officer works in the field, while the Electoral Registration Officer takes statutory decisions on electoral rolls. The commission said field officers have role-based ECINet access and that people left out of SIR can seek inclusion through continuous updation.$$,
  $$Election Commission meeting decisions of 26 September 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315309&reg=3&lang=1$$,
  $$Election Commission of India / Press Information Bureau$$, $$2026-09-26$$,
  $$["BLO means Booth Level Officer and ERO means Electoral Registration Officer.","The Commission directed home visits for specified persons issued SIR notices to collect documents.","A committee including an independent IIT or IIIT expert will review ECINet compliance.","Continuous updation enables eligible persons left out of SIR to apply for inclusion in electoral rolls."]$$::jsonb,
  $$[{"question":"Who makes the statutory decision on an electoral-roll case after field collection?","answer":"The Electoral Registration Officer (ERO)."},{"question":"What is the purpose of continuous updation?","answer":"It allows eligible electors to seek inclusion or correction outside a one-time revision window."}]$$::jsonb,
  $${"title":"From field verification to an electoral-roll decision","steps":["A field officer assists with collection or verification of documents.","The material is recorded through the authorised electoral system.","The ERO takes the statutory decision.","Help desks and online options reduce access barriers for electors."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-tarang-shakti-2026-multilateral-air-exercise$$, $$2026-09-28$$,
  $$Exercise Tarang Shakti 2026 begins its operational phase at Jodhpur$$,
  $$The Indian Air Force began the operational phase of Exercise Tarang Shakti 2026 at Air Force Station Jodhpur. The 26 September–12 October multilateral exercise includes Australia, Bangladesh, France, Germany, Sri Lanka, the UAE and the United States.$$,
  $$This is a defence-cooperation update. The exam value is in the exercise name, venue, participating countries and the idea of interoperability rather than memorising every aircraft type.$$,
  $$Tarang Shakti was first held in 2024. The 2026 edition is themed Power in Partnership and is designed for joint training, operational exchange and common understanding among partner air forces.$$,
  $$Exercise Tarang Shakti 2026: Power in Partnership$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315563&reg=3&lang=1$$,
  $$Indian Air Force, Ministry of Defence / Press Information Bureau$$, $$2026-09-27$$,
  $$["Exercise Tarang Shakti 2026 is being held at Air Force Station Jodhpur.","Its operational phase runs from 26 September to 12 October 2026.","Seven foreign countries are participating: Australia, Bangladesh, France, Germany, Sri Lanka, UAE and USA.","The exercise emphasises interoperability, mutual learning and aerospace safety."]$$::jsonb,
  $$[{"question":"Which service leads Exercise Tarang Shakti?","answer":"The Indian Air Force."},{"question":"What does interoperability mean in a multinational exercise?","answer":"Forces can communicate, plan and operate together effectively."}]$$::jsonb,
  $${"title":"Why multilateral air exercises matter","steps":["Partner air forces bring aircraft, crews and planners together.","They practise agreed procedures across missions.","Shared experience improves interoperability and safety.","Professional links support later defence cooperation."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-admm-plus-maritime-security-jca$$, $$2026-09-28$$,
  $$INS Sahyadri and INS Kulish complete ADMM-Plus maritime-security activity$$,
  $$INS Sahyadri and INS Kulish concluded participation in the 23rd ADMM-Plus Experts Working Group on Maritime Security Joint Cooperation Activity at Subic Bay, Philippines. The activity included operational synchronisation, a tabletop exercise and a sea-phase planning conference.$$,
  $$This brings together Indo-Pacific geography, ASEAN-centred defence dialogue and India Act East engagement. It is not a bilateral naval exercise with the Philippines alone.$$,
  $$ADMM-Plus is the ASEAN Defence Ministers Meeting Plus framework. The official release links India participation to its Act East Policy and the MAHASAGAR vision: Mutual and Holistic Advancement for Security and Growth Across Regions.$$,
  $$Indian Naval Ships Sahyadri and Kulish conclude participation in ADMM-Plus maritime-security activity$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315585&reg=3&lang=1$$,
  $$Indian Navy, Ministry of Defence / Press Information Bureau$$, $$2026-09-27$$,
  $$["INS Sahyadri is a stealth frigate and INS Kulish is a missile corvette.","The activity was the 23rd ADMM-Plus Experts Working Group on Maritime Security Joint Cooperation Activity.","It was held at Subic Bay in the Philippines.","MAHASAGAR expands to Mutual and Holistic Advancement for Security and Growth Across Regions."]$$::jsonb,
  $$[{"question":"What does ADMM stand for?","answer":"ASEAN Defence Ministers Meeting."},{"question":"Where was the cited maritime-security activity held?","answer":"Subic Bay, Philippines."}]$$::jsonb,
  $${"title":"An ASEAN-centred maritime cooperation setting","steps":["Partner navies meet through the ADMM-Plus framework.","Experts exchange procedures and coordinate plans.","Ships and crews conduct practical cooperation activity.","The work builds confidence and regional maritime awareness."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-kandla-port-e-methanol-facility$$, $$2026-09-28$$,
  $$Foundation stone laid for India first port-based e-methanol facility at Kandla$$,
  $$The foundation stone was laid for a 150-tonne-per-day e-methanol facility at Deendayal Port Authority, Kandla. The ₹2,300-crore DPA–Assam Petro-Chemicals project is planned in two phases and will use renewable power, water and biogenic carbon dioxide to make shipping fuel.$$,
  $$This is a clean-maritime-fuel and port-infrastructure development. Treat the announcement accurately as a project under development, not an operating plant.$$,
  $$E-methanol is methanol made using low-carbon inputs such as renewable electricity and captured biogenic carbon dioxide. The release places the facility in the context of cleaner shipping and India net-zero target for 2070.$$,
  $$India first port-based e-methanol production facility to produce and supply green fuel to ships$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315327&reg=3&lang=1$$,
  $$Ministry of Ports, Shipping and Waterways / Press Information Bureau$$, $$2026-09-26$$,
  $$["The facility is proposed at Deendayal Port Authority in Kandla, Gujarat.","Its planned capacity is 150 tonnes of e-methanol a day.","DPA and Assam Petro-Chemicals Ltd are the project partners.","The project is planned in phases and is linked to cleaner shipping and the net-zero 2070 goal."]$$::jsonb,
  $$[{"question":"Which port authority is associated with the e-methanol project?","answer":"Deendayal Port Authority at Kandla."},{"question":"Why is e-methanol relevant to shipping?","answer":"It can serve as a lower-carbon fuel made with renewable and biogenic inputs."}]$$::jsonb,
  $${"title":"A port-based green-fuel chain","steps":["Renewable power and water help produce green hydrogen.","Biogenic carbon dioxide supplies the carbon input.","The plant synthesises e-methanol.","Port logistics can supply the fuel to ships."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-worldskills-shanghai-india-performance$$, $$2026-09-28$$,
  $$India finishes tenth at WorldSkills Shanghai 2026$$,
  $$India ranked tenth at the 48th WorldSkills Competition in Shanghai, with six silver medals and 20 Medallions for Excellence. The 70-member Indian contingent competed in 63 skills, improving on the country’s 13th-place finish at WorldSkills Lyon 2024.$$,
  $$This is a skilling and international-organisations brief. It links global benchmarking with domestic skill-development institutions rather than treating it as an academic Olympiad.$$,
  $$WorldSkills is a biennial international competition for vocational and technical skills. India participation was coordinated by the National Skill Development Corporation under the Ministry of Skill Development and Entrepreneurship.$$,
  $$India ranks tenth at WorldSkills Shanghai 2026, wins six silver medals and 20 Medallions for Excellence$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315640&reg=3&lang=1$$,
  $$Ministry of Skill Development and Entrepreneurship / Press Information Bureau$$, $$2026-09-27$$,
  $$["WorldSkills Shanghai 2026 was the 48th WorldSkills Competition.","India ranked tenth, compared with thirteenth at WorldSkills Lyon 2024.","India won six silver medals and 20 Medallions for Excellence.","NSDC coordinated India participation under the Ministry of Skill Development and Entrepreneurship."]$$::jsonb,
  $$[{"question":"Which body coordinated India participation at WorldSkills Shanghai?","answer":"National Skill Development Corporation (NSDC)."},{"question":"How often is the WorldSkills Competition held?","answer":"Every two years."}]$$::jsonb,
  $${"title":"Global skills benchmarking","steps":["Countries select and prepare skilled competitors.","Competitors demonstrate vocational and technical skills against common standards.","Results identify performance and learning opportunities.","Training institutions can adapt methods and assessments using the feedback."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-nmdc-nagarnar-pellet-and-slurry-project$$, $$2026-09-28$$,
  $$NMDC commissions integrated iron-ore processing and pellet facilities in Chhattisgarh$$,
  $$NMDC commissioned a ₹5,427-crore integrated project connecting Bacheli and Nagarnar: an iron-ore processing plant, a 135-km 15-MTPA slurry pipeline and a 2-MTPA pellet plant. The Nagarnar plant processes material from the Bailadila mines into pellets for steelmaking.$$,
  $$This is a minerals-to-steel value-chain update. It is useful for distinguishing raw iron ore, concentrate and pellets, and for locating the project in Bastar, Chhattisgarh.$$,
  $$Pelletisation converts processed iron-ore concentrate into uniform pellets that are used as a steelmaking feed. A slurry pipeline moves a mixture of fine ore and water, reducing the need for road transport of concentrate.$$,
  $$NMDC commissions iron-ore processing plant, slurry pipeline and pellet plant in Bastar, Chhattisgarh$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315705&reg=3&lang=1$$,
  $$Ministry of Steel / Press Information Bureau$$, $$2026-09-27$$,
  $$["The integrated NMDC project links Bacheli with Nagarnar in Chhattisgarh.","It includes a 15-MTPA slurry pipeline of 135 km and a 2-MTPA pellet plant.","The project cost is stated as ₹5,427 crore.","Pellets are a processed iron-ore feed used in steelmaking."]$$::jsonb,
  $$[{"question":"What does pelletisation do to iron-ore concentrate?","answer":"It converts it into uniform pellets for use in steelmaking."},{"question":"Which State hosts the cited NMDC project?","answer":"Chhattisgarh."}]$$::jsonb,
  $${"title":"From mine fines to steelmaking feed","steps":["Iron ore is mined and processed into concentrate.","A slurry pipeline transports concentrate to the downstream site.","The pellet plant converts concentrate into pellets.","Pellets become a more suitable feed for steelmaking processes."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-bharat-maritime-insurance-pool$$, $$2026-09-28$$,
  $$PIB backgrounder explains Bharat Maritime Insurance Pool coverage and safeguards$$,
  $$A PIB backgrounder set out the Bharat Maritime Insurance Pool’s domestic coverage for hull and machinery, cargo, protection and indemnity, and war risks. Launched in May 2026, the pool has stated capacity of ₹13,906.50 crore (USD 1.5 billion) and uses member insurers’ combined underwriting and reinsurance capacity.$$,
  $$This is a financial-sector and maritime-security item. It tests the meaning of P&I insurance and the difference between an insurance pool and a port or shipbuilding scheme.$$,
  $$The backgrounder says BMIP was approved on 18 April and launched on 12 May 2026. Claims up to USD 100 million are met from reserves and reinsurance recoveries; a sovereign guarantee is relevant only after the pool reserves are exhausted.$$,
  $$Bharat Maritime Insurance Pool$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315489&reg=3&lang=1$$,
  $$PIB Backgrounder, Government of India$$, $$2026-09-27$$,
  $$["BMIP was formally launched on 12 May 2026 after approval on 18 April 2026.","Its stated capacity is ₹13,906.50 crore, or USD 1.5 billion.","Coverage includes Hull and Machinery, Cargo, Protection and Indemnity, and War risks.","P&I insurance can cover liabilities such as collisions, pollution and crew injuries."]$$::jsonb,
  $$[{"question":"What does P&I stand for in marine insurance?","answer":"Protection and Indemnity."},{"question":"When does the stated sovereign guarantee become relevant for BMIP claims?","answer":"Only after pool reserves are exhausted for larger claims."}]$$::jsonb,
  $${"title":"How a domestic insurance pool shares maritime risk","steps":["Domestic insurers contribute underwriting capacity.","The pool issues cover for defined marine risks.","Members collectively reinsure their allocated risk.","Reserves and reinsurance meet claims before any sovereign backstop is considered."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-power-from-waste-resource-recovery$$, $$2026-09-28$$,
  $$PIB backgrounder traces resource recovery from organic waste to fuel, power and manure$$,
  $$A PIB backgrounder on Power from Waste describes how organic waste streams such as cattle dung, kitchen waste, crop residue and market waste can be processed into biogas, compressed biogas, electricity and manure. It frames these as resource-recovery outcomes within scientific waste management.$$,
  $$This is useful environment and urban-governance context. The core concept is the waste-to-resource chain; it should not be confused with incineration of all municipal waste.$$,
  $$Biogas is produced by anaerobic digestion of biodegradable material. Its upgrading can yield compressed biogas, while the digestate can be used as manure; suitable feedstock segregation is essential for such systems.$$,
  $$Power from Waste$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315501&reg=3&lang=1$$,
  $$PIB Backgrounder, Government of India$$, $$2026-09-27$$,
  $$["Biodegradable waste can produce biogas through anaerobic digestion.","Upgraded biogas can be used as compressed biogas (CBG).","Digestate from biogas systems can be used as manure.","Waste-to-resource systems depend on suitable feedstock and segregation."]$$::jsonb,
  $$[{"question":"Which process produces biogas from biodegradable matter without oxygen?","answer":"Anaerobic digestion."},{"question":"What useful by-product can remain after biogas production?","answer":"Digestate that can be used as manure."}]$$::jsonb,
  $${"title":"Organic waste to useful products","steps":["Biodegradable waste is segregated and collected.","Anaerobic digestion produces biogas.","Biogas may be used for energy or upgraded to CBG.","Digestate can return nutrients to soil as manure."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-28-first-lng-powered-train-sabarmati$$, $$2026-09-28$$,
  $$India first LNG-powered train is flagged off from Sabarmati$$,
  $$A country-first LNG-powered train was flagged off from Sabarmati Railway Station in Ahmedabad. The same release records commissioning of a WAG-12 maintenance shed and introduction of Kavach on the Sabarmati–Kalol–Sabarmati section.$$,
  $$This is a rail-technology and transport-energy update. The publication is centred on a completed flag-off; it should not be read as evidence that the entire rail network has converted to LNG.$$,
  $$Liquefied natural gas is natural gas cooled into liquid form for easier storage and transport. Kavach is India’s automatic train-protection system; it is distinct from a propulsion fuel change.$$,
  $$Country first LNG-powered train flagged off from Sabarmati Railway Station$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315543&reg=3&lang=1$$,
  $$Ministry of Home Affairs / Press Information Bureau$$, $$2026-09-27$$,
  $$["The LNG-powered train was flagged off from Sabarmati Railway Station in Ahmedabad.","LNG means liquefied natural gas.","A WAG-12 maintenance shed was inaugurated at Sabarmati.","Kavach was introduced on the Sabarmati–Kalol–Sabarmati railway section."]$$::jsonb,
  $$[{"question":"What does LNG stand for?","answer":"Liquefied natural gas."},{"question":"What is Kavach in the railway context?","answer":"India’s automatic train-protection system."}]$$::jsonb,
  $${"title":"Separate layers of railway modernisation","steps":["A traction or fuel technology changes how a train is powered.","Maintenance facilities support locomotive reliability.","Automatic train protection helps prevent unsafe train movements.","Network projects can combine efficiency, safety and lower-emission objectives."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-09-28-eci-sir-access-and-ecinet-review$$,
  $$2026-09-28-tarang-shakti-2026-multilateral-air-exercise$$,
  $$2026-09-28-admm-plus-maritime-security-jca$$,
  $$2026-09-28-kandla-port-e-methanol-facility$$,
  $$2026-09-28-worldskills-shanghai-india-performance$$,
  $$2026-09-28-nmdc-nagarnar-pellet-and-slurry-project$$,
  $$2026-09-28-bharat-maritime-insurance-pool$$,
  $$2026-09-28-power-from-waste-resource-recovery$$,
  $$2026-09-28-first-lng-powered-train-sabarmati$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
